// 1. REST long-polling — simplest; reconnect loop in user code
async function longPoll(url: string, onMsg: (m: unknown) => void) {
  while (true) {
    try {
      const r = await fetch(url + '?since=' + lastSeen, { signal: abortCtrl.signal });
      if (!r.ok) throw new Error('poll failed ' + r.status);
      const batch = await r.json();
      for (const m of batch.events) onMsg(m);
      lastSeen = batch.cursor;
    } catch (e) {
      await sleep(backoff());   // exponential backoff + jitter
    }
  }
}

// 2. Server-Sent Events — browser native, auto-reconnects, resumes via Last-Event-ID
const es = new EventSource('/api/v1/notifications', { withCredentials: true });
es.onmessage = e => render(JSON.parse(e.data));
es.addEventListener('order.updated', e => updateOrder(JSON.parse(e.data)));
es.onerror = () => {
  // EventSource auto-reconnects; just log
  console.warn('SSE reconnecting...');
};

// 3. WebSocket — full duplex; manage reconnect + resubscribe yourself
const ws = new WebSocket('wss://chat.example.com/v1/ws');
ws.binaryType = 'arraybuffer';
ws.onopen    = () => ws.send(JSON.stringify({ type: 'auth', token }));
ws.onmessage = ev => dispatch(JSON.parse(ev.data));
ws.onclose   = ev => scheduleReconnect(ev.code, ev.reason);
ws.onerror   = err => log.error(err);

// SSE via Spring MVC — return Flux<ServerSentEvent<T>> from WebFlux, or SseEmitter in MVC
@RestController
@RequestMapping("/api/v1/notifications")
class NotificationController {

    private final NotificationStream stream;

    @GetMapping(produces = MediaType.TEXT_EVENT_STREAM_VALUE)
    public Flux<ServerSentEvent<Notification>> subscribe(
            @AuthenticationPrincipal User user,
            @RequestHeader(value = "Last-Event-ID", required = false) String lastId) {
        return stream.forUser(user.id(), lastId)                 // resume from id
            .map(n -> ServerSentEvent.<Notification>builder()
                .id(n.id())
                .event(n.type())                                  // 'order.updated', etc.
                .data(n)
                .retry(Duration.ofSeconds(5))
                .build())
            .doOnCancel(() -> log.info("user {} disconnected", user.id()));
    }
}

// WebSocket via Spring — programmatic handler (no STOMP)
@Configuration
@EnableWebSocket
class WsConfig implements WebSocketConfigurer {
    @Override public void registerWebSocketHandlers(WebSocketHandlerRegistry reg) {
        reg.addHandler(new ChatHandler(), "/ws/chat")
           .setAllowedOrigins("https://app.example.com")
           .addInterceptors(new AuthHandshakeInterceptor());
    }
}

class ChatHandler extends TextWebSocketHandler {
    @Override
    protected void handleTextMessage(WebSocketSession session, TextMessage msg) {
        // fan-out via shared bus (Redis pub/sub, Kafka) if multi-instance
        broker.publish(msg.getPayload());
    }
    @Override
    public void afterConnectionEstablished(WebSocketSession s) {
        // re-subscribe logic; tokens already validated in handshake interceptor
    }
}
